#include "rsr_private.h"
#include "rf.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/
                                      
/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*        I N L I N E   F U N C T I O N S   &   T E M P L A T E S           */
/*==========================================================================*/
void rsr_valet_toogle (void * arg)
{
  if(rsr_vars.valet_mode)
    {
      rsr_valet_off(NULL) ;
    }
  else
    {
      rsr_valet_on(NULL) ;
    }
}
//--------------------------------------------------------------------------//

void rsr_valet_on (void * arg)
{
  rsr_vars.valet_mode = TRUE ;

  rf_icon_set  (ICON_VALET  , TRUE) ;

  #if DBG_RSR == 1
    dbg_tx_text ("\nrsr valet ON") ;
  #endif
}
//--------------------------------------------------------------------------//

void rsr_valet_off (void * arg)
{
   rsr_vars.valet_mode = FALSE ;

   rf_icon_clr  (ICON_VALET  , TRUE) ;

   #if DBG_RSR == 1
    dbg_tx_text ("\nrsr valet OFF") ;
   #endif
}

